import { Link } from '@tanstack/react-router';
import { forwardRef, type ComponentPropsWithoutRef } from 'react';

// Some destinations are generated by the backend or include an existing
// query string. Keep these links on the same route tree as typed route links.
export default forwardRef<HTMLAnchorElement, ComponentPropsWithoutRef<'a'> & { href: string; scroll?: boolean }>(
    function ConsoleLink({ href, scroll, ...props }, ref) {
        if (!href.startsWith('/') || href.startsWith('//')) {
            return <Link ref={ref} to={href} resetScroll={scroll} {...props} />;
        }
        return <Link ref={ref} to="." href={href} resetScroll={scroll} {...props} />;
    }
);
